// Generate a filename that points to an existing file filled with random data
const char *path = FUZZ_PARAM_FILENAME();
FILE *f = fopen(path, "rb");
if(!f) { /* stream must be valid and opened for reading */ FUZZ_BAIL(); }

// Randomly choose size and nmemb while keeping total bytes modest (<= 2048)
unsigned int r1 = *FUZZ_PARAM(unsigned int);
unsigned int r2 = *FUZZ_PARAM(unsigned int);
size_t size = (r1 % 2) ? 0 : ((r1 % 128) + 1);         // sometimes exercise size==0
size_t nmemb = (r2 % 2) ? 0 : ((r2 % 32) + 1);          // sometimes exercise nmemb==0

// Enforce total bytes cap and ensure buffer is large enough
size_t total = size * nmemb;
if(total > 2048) {
    // shrink nmemb to fit under cap, preserving as much variety as possible
    nmemb = (size == 0) ? 0 : (2048 / size);
    total = size * nmemb;
}

// Allocate writable buffer; must be valid when total > 0 (requirements)
std::vector<unsigned char> buf(total ? total : 1u);

// Perform the read
size_t got = fread(buf.data(), size, nmemb, f);

// If size==0 or nmemb==0, fread must return 0 without accessing ptr
if(size == 0 || nmemb == 0) { FUZZ_ASSERT(got == 0, "fread must return 0 when size==0 or nmemb==0"); }

// Probe stream state to exercise partial-read paths
int eof_flag = feof(f);
int err_flag = ferror(f);
(void)eof_flag; (void)err_flag;

fclose(f);

// Validation: Ensures buffer validity for non-zero reads, stream opened for read, caps total bytes, and asserts zero-length contract. Partial reads are allowed; feof/ferror probed.

// Prepare data buffer to write
std::string payload = FUZZ_PARAM_STR();
// Limit to 2048 bytes for performance; use a slice into payload
size_t max_bytes = payload.size();
if(max_bytes > 2048) max_bytes = 2048;

// Randomly choose size and nmemb under the available payload
unsigned int r1 = *FUZZ_PARAM(unsigned int);
unsigned int r2 = *FUZZ_PARAM(unsigned int);
size_t size = (r1 % 2) ? 0 : ((r1 % 128) + 1);          // sometimes exercise size==0
size_t nmemb = (r2 % 2) ? 0 : ((r2 % 32) + 1);           // sometimes exercise nmemb==0
size_t total = size * nmemb;

// Fit the total to available buffer and cap
if(total > max_bytes) {
    nmemb = (size == 0) ? 0 : (max_bytes / size);
    total = size * nmemb;
}

// Open a writable stream
const char *path = FUZZ_PARAM_FILENAME();
FILE *f = fopen(path, "wb+");
if(!f) { FUZZ_BAIL(); }

// When total is zero, fwrite must return 0
const void *ptr = payload.data();
size_t wrote = fwrite(ptr, size, nmemb, f);
if(size == 0 || nmemb == 0) { FUZZ_ASSERT(wrote == 0, "fwrite must return 0 when size==0 or nmemb==0"); }

// Flush and optionally read back a small chunk to exercise I/O paths
fflush(f);

// Seek and read back up to 64 bytes to exercise read path on update mode
fseek(f, 0, SEEK_SET);
{
    unsigned char rb[64];
    size_t toread = (wrote * size < sizeof(rb)) ? (wrote * size) : sizeof(rb);
    if(toread) { fread(rb, 1, toread, f); }
}

fclose(f);

// Validation: Ensures writable stream, keeps total <= payload size and <= 2048, asserts zero-length contract, flushes and probes read-back to increase coverage.

// Generate two arbitrary strings; c_str() yields NUL-terminated bytes
std::string a = FUZZ_PARAM_STR();
std::string b = FUZZ_PARAM_STR();

int r = strcasecmp(a.c_str(), b.c_str());
(void)r; // Sign of r is meaningful to callers; we just exercise

// Property: comparing a string to itself must be equal (case-insensitive)
int self = strcasecmp(a.c_str(), a.c_str());
FUZZ_ASSERT(self == 0, "strcasecmp(s, s) must be 0");

// Validation: Supplies valid NUL-terminated strings and asserts reflexivity; no resources are persisted.

// Generate two strings and a comparison bound n
std::string a = FUZZ_PARAM_STR();
std::string b = FUZZ_PARAM_STR();

size_t maxn = a.size() > b.size() ? a.size() : b.size();
unsigned int r = *FUZZ_PARAM(unsigned int);
// Choose n in [0, maxn*2] to exercise both shorter and longer-than-string cases (bounded to 4096*2)
size_t n = (maxn ? (r % (maxn * 2 + 1)) : (r % 5));

int res = strncasecmp(a.c_str(), b.c_str(), n);
(void)res;

// Property: comparing a string to itself for any n must be equal
int self = strncasecmp(a.c_str(), a.c_str(), n);
FUZZ_ASSERT(self == 0, "strncasecmp(s, s, n) must be 0 for all n");

// Validation: Provides valid NUL-terminated inputs, random n including 0, and asserts reflexivity over bounded compare.

// Build a safe, controlled format string and matching arguments to avoid UB.
// We pick among a small set of vetted formats using a fuzzed selector.
int i1 = (int)(*FUZZ_PARAM(unsigned int) & 0x7FFFFFFF);
int i2 = (int)(*FUZZ_PARAM(unsigned int) & 0x7FFFFFFF);
int i3 = (int)(*FUZZ_PARAM(unsigned int) & 0x7FFFFFFF);
long l1 = (long)(*FUZZ_PARAM(unsigned int));
long long ll1 = ((long long)(*FUZZ_PARAM(unsigned int)) << 32) ^ (long long)(*FUZZ_PARAM(unsigned int));
unsigned int u1 = *FUZZ_PARAM(unsigned int);
double d1 = *(const double*)FUZZ_PARAM(double);
int width = (int)(*FUZZ_PARAM(unsigned int) % 61) - 10; // [-10,50]
std::string s = FUZZ_PARAM_STR();
if(s.size() > 64) s.resize(64); // keep it small to avoid huge outputs
const char *cstr = s.c_str();
void *p1 = (void *)&i1;
unsigned int sel = *FUZZ_PARAM(unsigned int) % 6;
int rc = 0;
switch(sel) {
  case 0: {
    const char *fmt = "Hello %% World"; // literal percent
    rc = curl_mprintf(fmt);
    break;
  }
  case 1: {
    const char *fmt = "Ints: %d %x %+d\n";
    rc = curl_mprintf(fmt, i1, i2, i3);
    break;
  }
  case 2: {
    const char *fmt = "Longs: %ld %lld Unsigned:%u\n";
    rc = curl_mprintf(fmt, l1, ll1, u1);
    break;
  }
  case 3: {
    const char *fmt = "Str: %.20s END\n"; // precision limits copy length
    rc = curl_mprintf(fmt, cstr);
    break;
  }
  case 4: {
    const char *fmt = "Ptr: %p End\n";
    rc = curl_mprintf(fmt, p1);
    break;
  }
  case 5: {
    const char *fmt = "Width/Prec int:%*d float:%.3f\n";
    rc = curl_mprintf(fmt, width, i1, d1);
    break;
  }
}
// Negative return indicates error per API contract
if(rc < 0) { FUZZ_BAIL(); }
// No persistent outputs; all data was ephemeral

// Prepare a writable FILE* using a fuzzed filename, ensure it is valid, then print.
const char *path = FUZZ_PARAM_FILENAME();
std::string mode = "wb+"; // writable binary; avoids locale/text variance
FILE *fd = fopen(path, mode.c_str());
if(!fd) { FUZZ_BAIL(); }
int i1 = (int)(*FUZZ_PARAM(unsigned int) & 0x7FFFFFFF);
unsigned int u1 = *FUZZ_PARAM(unsigned int);
double d1 = *(const double*)FUZZ_PARAM(double);
std::string s = FUZZ_PARAM_STR(); if(s.size() > 64) s.resize(64);
const char *cstr = s.c_str();
int rc = 0;
unsigned int sel = *FUZZ_PARAM(unsigned int) % 4;
switch(sel) {
  case 0: rc = curl_mfprintf(fd, "Hi %d %% %u\n", i1, u1); break;
  case 1: rc = curl_mfprintf(fd, "%.16s\n", cstr); break;
  case 2: rc = curl_mfprintf(fd, "Float: %.2f\n", d1); break;
  case 3: rc = curl_mfprintf(fd, "Mix: %d %u %.5s %.3f\n", i1, u1, cstr, d1); break;
}
if(rc < 0) { fclose(fd); FUZZ_BAIL(); }
// Close the stream to flush and release the resource
fclose(fd);

// Unsafe sprintf-equivalent; we ensure the buffer is sufficiently large and inputs are small.
char buffer[1024];
int i1 = (int)(*FUZZ_PARAM(unsigned int) & 0x7FFFFFFF);
long long ll1 = ((long long)(*FUZZ_PARAM(unsigned int)) << 32) ^ (long long)(*FUZZ_PARAM(unsigned int));
unsigned int u1 = *FUZZ_PARAM(unsigned int);
double d1 = *(const double*)FUZZ_PARAM(double);
std::string s = FUZZ_PARAM_STR(); if(s.size() > 64) s.resize(64);
const char *cstr = s.c_str();
int width = (int)(*FUZZ_PARAM(unsigned int) % 21); // [0,20]
int rc = 0;
unsigned int sel = *FUZZ_PARAM(unsigned int) % 5;
switch(sel) {
  case 0: rc = curl_msprintf(buffer, "Static text %% done"); break;
  case 1: rc = curl_msprintf(buffer, "I:%d U:%u L:%lld", i1, u1, ll1); break;
