import random
from typing import List

# Generator for MIME type strings suitable for curl_mime_type(part, ...)
# We return bytes that represent a NUL-terminated C string buffer. The fuzzer
# will likely read until NUL, so we include a terminating NUL and keep size <= 4096.
# We aim to produce valid and interesting media types with optional parameters.

_TOP_TYPES = [
    "text", "image", "audio", "video", "application", "multipart", "message", "font", "model"
]

_TEXT_SUBTYPES = [
    "plain", "html", "css", "csv", "javascript", "xml", "markdown", "calendar", "vcard"
]

_IMAGE_SUBTYPES = [
    "png", "jpeg", "gif", "bmp", "webp", "tiff", "svg+xml", "avif", "heif"
]

_AUDIO_SUBTYPES = [
    "mpeg", "ogg", "wav", "aac", "flac", "webm"
]

_VIDEO_SUBTYPES = [
    "mp4", "ogg", "webm", "mpeg", "quicktime"
]

_APP_SUBTYPES = [
    "octet-stream", "json", "xml", "x-www-form-urlencoded", "pdf", "zip", "gzip",
    "ld+json", "protobuf", "x-msgpack", "sql", "x-tar", "zstd", "cbor", "wasm"
]

_MULTIPART_SUBTYPES = [
    "form-data", "mixed", "alternative", "related", "digest", "byteranges"
]

_MESSAGE_SUBTYPES = [
    "http", "partial", "rfc822"
]

_FONT_SUBTYPES = [
    "woff", "woff2", "otf", "ttf"
]

_MODEL_SUBTYPES = [
    "gltf-binary", "gltf+json", "stl", "obj"
]

# Common parameter names and value generators
_PARAM_NAMES = [
    "charset", "boundary", "name", "filename", "format", "type", "q", "level", "profile"
]

_CHARSETS = ["utf-8", "utf-16", "iso-8859-1", "us-ascii", "windows-1252"]

_BOUNDARY_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'()+_,-./:=?"
_TOKEN_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$&+-.^_`|~"

def _rand_token(rng: random.Random, min_len=1, max_len=16) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(_TOKEN_CHARS) for _ in range(n))

def _rand_boundary(rng: random.Random) -> str:
    n = rng.randint(12, 60)
    return ''.join(rng.choice(_BOUNDARY_CHARS) for _ in range(n))

def _pick_subtype(rng: random.Random, top: str) -> str:
    table = {
        "text": _TEXT_SUBTYPES,
        "image": _IMAGE_SUBTYPES,
        "audio": _AUDIO_SUBTYPES,
        "video": _VIDEO_SUBTYPES,
        "application": _APP_SUBTYPES,
        "multipart": _MULTIPART_SUBTYPES,
        "message": _MESSAGE_SUBTYPES,
        "font": _FONT_SUBTYPES,
        "model": _MODEL_SUBTYPES,
    }
    lst = table.get(top, ["octet-stream"])  # fallback
    return rng.choice(lst)

def _maybe_quote(rng: random.Random, value: str) -> str:
    # Quote with simple quoted-string, escaping quotes and backslashes as needed
    if rng.random() < 0.4 or any(c in value for c in (' ', ';', '"', '\\', '=')):
        esc = value.replace('\\', '\\\\').replace('"', '\\"')
        return f'"{esc}"'
    return value

def _build_params(rng: random.Random, top: str, subtype: str) -> List[str]:
    params: List[str] = []

    # Useful defaults: charset for text and xml-ish types
    if top == "text" or subtype.endswith("xml") or "+xml" in subtype:
        if rng.random() < 0.9:
            params.append(f"charset={rng.choice(_CHARSETS)}")

    # Boundary for multipart
    if top == "multipart":
        # RFC requires boundary parameter
        boundary = _rand_boundary(rng)
        params.append(f"boundary={_maybe_quote(rng, boundary)}")

    # For form-data, sometimes include name/filename
    if top == "multipart" and subtype == "form-data":
        if rng.random() < 0.7:
            params.append(f"name={_maybe_quote(rng, _rand_token(rng, 3, 10))}")
        if rng.random() < 0.7:
            params.append(f"filename={_maybe_quote(rng, _rand_token(rng, 5, 12))}")

    # Quality factor occasionally
    if rng.random() < 0.2:
        q = rng.uniform(0.0, 1.0)
        params.append(f"q={q:.3f}")

    # Arbitrary additional params
    extra_count = rng.randint(0, 3)
    used = {p.split('=')[0] for p in params}
    for _ in range(extra_count):
        name = rng.choice(_PARAM_NAMES)
        if name in used and rng.random() < 0.7:
            continue
        used.add(name)
        val_source = rng.random()
        if name == "charset":
            val = rng.choice(_CHARSETS)
        elif name == "boundary":
            val = _rand_boundary(rng)
        elif name == "q":
            val = f"{rng.uniform(0.0,1.0):.3f}"
        else:
            val = _rand_token(rng, 1, 20)
        params.append(f"{name}={_maybe_quote(rng, val)}")

    return params

def _build_mime_type(rng: random.Random) -> str:
    # Sometimes generate extremely common types directly
    common = [
        "application/octet-stream",
        "text/plain; charset=utf-8",
        "application/json",
        "multipart/form-data; boundary=" + _rand_boundary(rng),
        "application/x-www-form-urlencoded",
        "image/png",
    ]
    if rng.random() < 0.25:
        return rng.choice(common)

    top = rng.choice(_TOP_TYPES)
    subtype = _pick_subtype(rng, top)

    # Optional structured suffix like +json or +xml for application/*
    if top == "application" and rng.random() < 0.3 and "+" not in subtype:
        subtype = subtype + rng.choice(["+json", "+xml"]) if rng.random() < 0.7 else subtype

    params = _build_params(rng, top, subtype)
    mime = f"{top}/{subtype}"
    if params:
        mime += "; " + "; ".join(params)
    return mime


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Create between 1 and 3 alternative MIME types joined by commas occasionally,
    # though curl_mime_type expects a single media type string. We mostly return a single one.
    if rng.random() < 0.15:
        count = rng.randint(2, 3)
        types = [_build_mime_type(rng) for _ in range(count)]
        s = ", ".join(types)
    else:
        s = _build_mime_type(rng)

    # Ensure length limit and NUL-terminate for C
    max_len = 4095  # leave room for NUL to stay <= 4096
    enc = s.encode('ascii', errors='ignore')[:max_len]
    return enc + b"\x00"
